const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const money=(n)=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:2}).format(Number(n||0));
const number=(n,d=3)=>new Intl.NumberFormat('en-IN',{maximumFractionDigits:d}).format(Number(n||0));
const esc=(v)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=(v)=>v?new Date(`${v}T00:00:00`).toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'}):'—';
const state={user:null,boot:null,page:'dashboard',offlineQueue:JSON.parse(localStorage.getItem('offline-orders')||'[]'),cache:{}};
async function api(path,opts={}){const res=await fetch('/api'+path,{...opts,headers:{...(opts.body?{'Content-Type':'application/json'}:{}),...(opts.headers||{})},body:opts.body?JSON.stringify(opts.body):undefined});if(!res.ok){let e;try{e=await res.json()}catch{};const err=new Error(e?.error||`Request failed (${res.status})`);err.status=res.status;err.detail=e;throw err;}if(res.headers.get('Content-Type')?.includes('application/pdf')||res.headers.get('Content-Type')?.includes('text/csv'))return res;return res.status===204?null:res.json();}
function toast(message,kind='success'){const el=document.createElement('div');el.className=`toast ${kind}`;el.textContent=message;$('#toast-region').append(el);setTimeout(()=>el.remove(),3800);}
function can(...roles){return roles.includes(state.user?.role)}
function titleCase(s){return String(s||'').replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase())}
function shell(content){const u=state.user;const nav=[['dashboard','Overview','◫',['owner','admin','salesman','production','auditor']],['orders','Orders','↗',['owner','admin','salesman','auditor']],['production','Production','⚙',['owner','admin','production','auditor']],['inventory','Inventory','▤',['owner','admin','production','auditor']],['invoices','Invoices & payments','▧',['owner','admin','auditor']],['reports','Audit reports','▥',['owner','admin','auditor']],['masters','Masters & access','⌘',['owner','admin']],['audit','Activity log','◷',['owner','admin','auditor']]];
  return `<div class="layout"><aside class="sidebar"><div class="brand"><div class="brand-mark">SF</div><div><strong>Sample Foods</strong><small>Order to Audit</small></div></div><div class="side-label">WORKSPACE</div><nav>${nav.filter(n=>n[3].includes(u.role)).map(n=>`<button class="nav-item ${state.page===n[0]?'active':''}" data-page="${n[0]}"><span class="nav-icon">${n[2]}</span>${n[1]}${n[0]==='orders'&&state.boot?.pending?'<i class="nav-count">'+state.boot.pending+'</i>':''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="connection"><span class="online-dot ${navigator.onLine?'':'offline'}"></span><span>${navigator.onLine?'Online':'Offline'}${state.offlineQueue.length?` · ${state.offlineQueue.length} queued`:''}</span></div><div class="user-card"><div class="avatar">${esc((u.name||u.username).split(' ').map(x=>x[0]).slice(0,2).join(''))}</div><div class="user-meta"><strong>${esc(u.name)}</strong><small>${esc(state.boot.role_names[u.role])}</small></div><button class="icon-btn" id="logout" title="Sign out">↪</button></div></div></aside><div class="mobilebar"><button id="mobile-menu" class="icon-btn">☰</button><strong>Sample Foods</strong><button id="mobile-sync" class="icon-btn">⟳</button></div><main class="main"><div class="topline"><div class="breadcrumb">Factory operations <span>/</span> <b>${titleCase(state.page)}</b></div><div class="top-actions"><span class="today-label">${date(state.boot.today)}</span>${state.offlineQueue.length?'<button class="button button-soft button-small" id="sync-orders">Sync queued orders ('+state.offlineQueue.length+')</button>':''}<span class="avatar small-avatar">${esc((u.name||u.username).split(' ').map(x=>x[0]).slice(0,2).join(''))}</span></div></div><div class="page-content">${content}</div></main></div>`;
}
function table(headers,rows,empty='No records yet.'){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.join(''):`<tr><td class="empty-cell" colspan="${headers.length}">${empty}</td></tr>`}</tbody></table></div>`}
function badge(status){const key=String(status||'').toLowerCase().replaceAll(' ','-');return `<span class="badge badge-${esc(key)}">${esc(titleCase(status))}</span>`}
function stat(label,val,detail,icon,extra=''){return `<article class="stat-card"><div class="stat-top"><span>${label}</span><span class="stat-icon">${icon}</span></div><div class="stat-value">${val}</div><div class="stat-detail">${detail||''}</div>${extra}</article>`}
function heading(kicker,title,desc,action=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`}
function modal(title,body,submitText='Save'){return `<div class="modal-backdrop" id="modal"><section class="modal"><header class="modal-head"><div><div class="eyebrow">WORKSPACE ACTION</div><h2>${title}</h2></div><button class="icon-btn" data-close>×</button></header><div class="modal-body">${body}</div><footer class="modal-foot"><button class="button button-quiet" data-close>Cancel</button><button class="button button-primary" id="modal-submit">${submitText}</button></footer></section></div>`}
function modalForm(title,fields,onSave,submitText='Save'){document.body.insertAdjacentHTML('beforeend',modal(title,fields,submitText));$('#modal-submit').onclick=async()=>{const btn=$('#modal-submit');btn.disabled=true;try{await onSave($('#modal'));$('#modal')?.remove()}catch(e){toast(e.message,'error');btn.disabled=false;}};$$('[data-close]',$('#modal')).forEach(x=>x.onclick=()=>$('#modal').remove());$('#modal').addEventListener('click',e=>{if(e.target.id==='modal')$('#modal').remove()});}
const field=(label,name,type='text',value='',attrs='')=>`<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`;
const selectField=(label,name,options,value='')=>`<label class="field"><span>${label}</span><select name="${name}">${options.map(o=>`<option value="${esc(o.value)}" ${String(o.value)===String(value)?'selected':''}>${esc(o.label)}</option>`).join('')}</select></label>`;
function readForm(root){return Object.fromEntries(new FormData(root.querySelector('form')||root).entries())}
function noAccess(msg){return `<section class="panel empty-state"><div class="empty-icon">⌁</div><h2>Nothing to show yet</h2><p>${msg}</p></section>`}

async function dashboard(){const d=await api('/dashboard');const ownOrders=can('salesman')?await api('/orders'):[],runList=can('admin','owner')?await api('/production'):[];state.cache.dashboard=d;let html=heading(can('salesman')?'FIELD SALES':'FACTORY SNAPSHOT',can('salesman')?'Your orders, at a glance':'Good to see you, '+esc(state.user.name.split(' ')[0]),can('salesman')?'A live view of your customer orders and their progress.':'Your daily operations, production health and cash position in one place.',can('salesman','admin','owner')?`<button class="button button-primary" id="quick-order">＋ New order</button>`:'');
  if(can('owner','admin','auditor'))html+=`<div class="stat-grid">${stat('Open invoice value',money(d.outstanding.reduce((s,x)=>s+x.total,0)),`${d.outstanding.length} open invoices`,'↗')}${stat('Outstanding',money(d.outstanding.reduce((s,x)=>s+x.balance,0)),'Customer receivables','◷')}${stat('Orders need attention',number(d.pending_orders,0),'Submitted or stock-short orders','▱')}${can('owner','admin')?stat('Latest run · cost / unit',runList[0]?money(runList[0].cost_per_unit):'—',runList[0]?`RUN-${runList[0].id} · ${number(runList[0].actual)} good output`:'No production run posted','⚙'):stat('Production runs',number(d.recent_runs.length,0),'Recent activity','⚙')}</div>`;
  if(can('salesman'))html+=`<div class="stat-grid">${stat('Your open orders',number(d.pending_orders,0),'Submitted and awaiting action','↗')}${stat('Orders this month',number(d.recent_orders.length,0),'Recent customer orders','▱')}${stat('Customers assigned',number(state.boot.customers.length,0),'In your route list','◉')}</div>`;
  if(d.open_shortages.length&&can('admin','owner'))html+=`<section class="alert-strip"><span class="alert-icon">!</span><div><strong>${d.open_shortages.length} order${d.open_shortages.length>1?'s':''} need stock review</strong><span>${d.open_shortages.map(x=>`${esc(x.customer)} · ${esc(x.note)}`).join(' &nbsp; / &nbsp; ')}</span></div><button class="text-button" data-go="orders">Review orders →</button></section>`;
  const varianceFlags=runList[0]?runList[0].inputs.filter(i=>Math.abs(i.variance)>(runList[0].tolerance_bps??300)/100):[];if(varianceFlags.length&&can('admin','owner'))html+=`<section class="alert-strip"><span class="alert-icon">!</span><div><strong>Production variance · RUN-${runList[0].id}</strong><span>Yield ${runList[0].yield_variance.toFixed(1)}% · ${varianceFlags.map(i=>`${esc(i.name)} ${i.variance>0?'+':''}${i.variance.toFixed(1)}%`).join(' · ')}</span></div><button class="text-button" data-go="production">Review run →</button></section>`;
  const stockRows=d.stock.filter(i=>i.kind!=='finished'||can('owner','admin','production')).slice(0,6).map(i=>`<tr><td><div class="item-cell"><span class="kind-dot ${i.kind}"></span><div><strong>${esc(i.name)}</strong><small>${esc(i.sku)}</small></div></div></td><td>${number(i.on_hand)} ${esc(i.unit)}</td><td>${i.low?'<span class="warning-text">Below reorder level</span>':'<span class="subtle">Healthy</span>'}</td></tr>`);
  const orderRows=d.recent_orders.slice(0,6).map(o=>`<tr><td><strong>#${o.id}</strong><small>${date(o.order_date)}</small></td><td>${esc(o.customer)}${o.salesman?`<small>${esc(o.salesman)}</small>`:''}</td><td>${number(o.quantity,0)} packets</td><td>${badge(o.status)}</td></tr>`);
  html+=`<div class="dashboard-grid"><section class="panel"><div class="panel-heading"><div><h2>${can('salesman')?'My recent orders':'Recent orders'}</h2><p>${can('salesman')?'Follow your customer order status':'Latest activity across the sales desk'}</p></div><button class="text-button" data-go="orders">All orders →</button></div>${table(['Order','Customer','Quantity','Status'],orderRows,'Your recent orders will appear here.')}</section>${can('salesman')?'':`<section class="panel"><div class="panel-heading"><div><h2>Stock on hand</h2><p>Live balance from the movement ledger</p></div><button class="text-button" data-go="inventory">Ledger →</button></div>${table(['Item','Balance','Signal'],stockRows,'No stock items.')}</section>`}</div>`;
  if(can('salesman')){const byCustomer=new Map();for(const o of ownOrders){const x=byCustomer.get(o.customer)||{customer:o.customer,orders:0,packets:0,value:0};x.orders++;x.packets+=o.quantity;x.value+=o.amount;byCustomer.set(o.customer,x)}html+=`<section class="panel"><div class="panel-heading"><div><h2>Customer-wise sales</h2><p>Salesman's submitted orders, before tax</p></div></div>${table(['Customer','Orders','Packets','Order value'],[...byCustomer.values()].map(x=>`<tr><td>${esc(x.customer)}</td><td>${x.orders}</td><td>${number(x.packets,0)}</td><td>${money(x.value)}</td></tr>`),'Your customer orders appear here.')}</section>`;}
  if(state.offlineQueue.length)html+=`<section class="sync-card"><div class="sync-symbol">⟳</div><div><strong>${state.offlineQueue.length} saved order${state.offlineQueue.length>1?'s':''} waiting to sync</strong><p>They are stored on this device and will be sent when your connection returns.</p></div><button class="button button-soft" id="sync-orders">Sync now</button></section>`;
  render(html);$('#quick-order')?.addEventListener('click',newOrder);$$('[data-go]').forEach(b=>b.onclick=()=>navigate(b.dataset.go));$('#sync-orders')?.addEventListener('click',syncOffline);
}
async function ordersPage(){const params=new URLSearchParams();const from=$('#from-date')?.value,to=$('#to-date')?.value;if(from)params.set('from',from);if(to)params.set('to',to);const rows=await api('/orders?'+params);let action=can('salesman','admin','owner')?'<button class="button button-primary" id="new-order">＋ Create order</button>':'';let html=heading('SALES LOOP','Orders','Capture field orders, verify availability, and follow each order through invoicing and dispatch.',action)+`<div class="filter-row"><label>From<input type="date" id="from-date" value="${esc(from||'')}"></label><label>To<input type="date" id="to-date" value="${esc(to||'')}"></label><button class="button button-soft" id="apply-filter">Apply filter</button><span class="filter-spacer"></span><span class="subtle">${rows.length} records</span></div>`;
  html+=table(['Order','Customer','Salesman','Items','Order value','Current status','Actions'],rows.map(o=>{const value=o.lines.reduce((s,l)=>s+l.quantity*l.price,0);let actions='';if(can('admin','owner')&&['submitted','shortage'].includes(o.status))actions=`<button class="button button-soft button-small" data-approve="${o.id}">Review & invoice</button> <button class="text-button danger-text" data-reject="${o.id}">Reject</button>`;else if(can('admin','owner')&&o.status==='invoiced')actions=`<button class="button button-primary button-small" data-dispatch="${o.id}">Record dispatch</button>`;else if(o.status==='invoiced')actions='<span class="subtle">Awaiting dispatch</span>';return `<tr><td><strong>#${o.id}</strong><small>${date(o.order_date)}</small></td><td><strong>${esc(o.customer)}</strong><small>${esc(o.state)}</small></td><td>${esc(o.salesman)}</td><td>${o.lines.map(l=>`${number(l.quantity,0)} × ${esc(l.name)}`).join('<br>')}</td><td>${money(value)}</td><td>${badge(o.status)}${o.note?`<small class="warning-text">${esc(o.note)}</small>`:''}</td><td>${actions||'—'}</td></tr>`}), 'No orders for this date range.');
  render(html);$('#new-order')?.addEventListener('click',newOrder);$('#apply-filter')?.addEventListener('click',ordersPage);$$('[data-approve]').forEach(b=>b.onclick=()=>reviewOrder(b.dataset.approve));$$('[data-reject]').forEach(b=>b.onclick=()=>rejectOrder(b.dataset.reject));$$('[data-dispatch]').forEach(b=>b.onclick=()=>dispatchOrder(b.dataset.dispatch));}
function orderLineHtml(products){const options=products.map(x=>`<option value="${x.id}">${esc(x.name)} · ${money(x.sell_price)}/${esc(x.unit)}</option>`).join('');const p=products[0],units=orderUnits(p);return `<div class="order-line"><label class="field"><span>Product</span><select class="order-product" name="product_id">${options}</select></label><label class="field"><span>Quantity</span><input name="quantity" type="number" min="0.001" step="0.001" value="1"></label><label class="field"><span>Order unit</span><select class="order-unit" name="unit">${units.map(u=>`<option value="${u.value}">${esc(u.label)}</option>`).join('')}</select></label><button type="button" class="icon-btn remove-line">×</button></div>`}
function orderUnits(product){const units=[{value:product.unit,label:product.unit}];if(product.unit==='packet'&&product.pack_size_milli)units.push({value:'carton',label:`carton (${number(product.pack_size_milli/1000,0)} packets)`});return units;}
function bindOrderUnits(products,root){$$('.order-line',root).forEach(row=>{$('.order-product',row).onchange=()=>{const p=products.find(x=>x.id===Number($('.order-product',row).value));$('.order-unit',row).innerHTML=orderUnits(p).map(u=>`<option value="${u.value}">${esc(u.label)}</option>`).join('')}})}
async function newOrder(){const c=state.boot.customers,products=state.boot.items.filter(i=>i.kind==='finished');if(!c.length||!products.length)return toast('No customers or finished products are configured yet.','error');const customerOptions=c.map(x=>({value:x.id,label:`${x.name} · ${x.state}`}));modalForm('Create customer order',`<form id="order-form" class="form-grid"><div class="span-2">${selectField('Customer','customer_id',customerOptions)}</div><div class="span-2" id="order-lines">${orderLineHtml(products)}</div><button type="button" class="button button-quiet span-2" id="add-order-line">＋ Add another product</button><div class="span-2">${field('Sales note','note')}</div></form>`,`Submit order`);
  $('#add-order-line').onclick=()=>{$('#order-lines').insertAdjacentHTML('beforeend',orderLineHtml(products));bindRemoveLines();bindOrderUnits(products,$('#order-lines'))};bindRemoveLines();bindOrderUnits(products,$('#order-lines'));$('#modal-submit').onclick=async()=>{try{const f=$('#order-form'),lines=$$('.order-line',f).map(r=>({item_id:Number($('[name=product_id]',r).value),quantity:Number($('[name=quantity]',r).value),unit:$('[name=unit]',r).value}));const payload={client_key:crypto.randomUUID(),customer_id:Number($('[name=customer_id]',f).value),lines,note:$('[name=note]',f).value};if(!navigator.onLine&&can('salesman')){state.offlineQueue.push(payload);localStorage.setItem('offline-orders',JSON.stringify(state.offlineQueue));$('#modal')?.remove();toast('Order saved on this device. It will sync when you are online.');await renderPage();return;}const res=await api('/orders',{method:'POST',body:payload});$('#modal')?.remove();toast(`Order #${res.id} submitted to the factory.`);state.cache={};await renderPage();}catch(e){toast(e.message,'error')}};}
function bindRemoveLines(){$$('.remove-line').forEach(b=>b.onclick=()=>{if($$('.order-line').length>1)b.closest('.order-line').remove()})}
async function syncOffline(){if(!navigator.onLine)return toast('You are still offline. The order remains saved on this device.','error');const items=[...state.offlineQueue];let sent=0;for(const order of items){try{await api('/orders',{method:'POST',body:order});sent++;}catch(e){if(e.status===401){toast('Sign in again before syncing the saved orders.','error');return;}toast(`Could not sync an order: ${e.message}`,'error');break;}}state.offlineQueue=items.slice(sent);localStorage.setItem('offline-orders',JSON.stringify(state.offlineQueue));toast(`${sent} order${sent===1?'':'s'} synced.`);await renderPage();}
async function reviewOrder(id){const orders=await api('/orders'),o=orders.find(x=>x.id===Number(id));if(!o)return;const lines=o.lines.map(l=>`<tr data-line="${l.id}"><td>${esc(l.name)}</td><td><input class="review-qty" type="number" min="1" value="${l.quantity}" /></td><td><input class="review-price" type="number" min="0" step="0.01" value="${l.price.toFixed(2)}" /></td></tr>`).join('');modalForm(`Review order #${o.id}`,`<p class="modal-intro">${esc(o.customer)} · ${date(o.order_date)} · ${esc(o.state)}</p><div class="table-wrap"><table><thead><tr><th>Product</th><th>Approved qty</th><th>Unit price ₹</th></tr></thead><tbody>${lines}</tbody></table></div><p class="subtle">Submitting creates the GST invoice. Dispatch remains a separate step.</p>`,'Approve & create invoice');$('#modal-submit').onclick=async()=>{try{const changes=$$('tr[data-line]',$('#modal')).map(r=>({id:Number(r.dataset.line),quantity:Number($('.review-qty',r).value),unit_price:Number($('.review-price',r).value)}));const r=await api(`/orders/${id}/approve`,{method:'POST',body:{lines:changes}});$('#modal')?.remove();toast(`Invoice created. Number #${r.invoice_id}.`);await renderPage();}catch(e){if(e.detail?.shortage){$('#modal')?.remove();const shortage=e.detail.shortage.map(s=>`${s.item}: available ${s.available}, requested ${s.requested}, short ${s.short}`).join('\n');toast(shortage,'error');}else toast(e.message,'error')}};}
async function rejectOrder(id){const reason=prompt('Why is this order being rejected?');if(reason===null)return;try{await api(`/orders/${id}/reject`,{method:'POST',body:{reason}});toast('Order rejected and the decision was logged.');await renderPage()}catch(e){toast(e.message,'error')}}
async function dispatchOrder(id){if(!confirm(`Record dispatch for order #${id}? Finished goods will be issued from stock.`))return;try{await api(`/orders/${id}/dispatch`,{method:'POST',body:{}});toast('Dispatch posted. Finished-goods stock and ledger updated.');await renderPage()}catch(e){toast(e.message,'error')}}

async function productionPage(){const [runs,items]=await Promise.all([api('/production'),Promise.resolve(state.boot.items)]);const products=items.filter(i=>i.kind==='finished'),materials=items.filter(i=>i.kind!=='finished');let html=heading('PRODUCTION FLOOR','Production runs','Post a recipe-based run once. The app checks material availability and updates raw and finished stock from the same transaction.',can('production','admin','owner')?'<button class="button button-primary" id="new-run">＋ Record production run</button>':'');
  const rows=runs.map(r=>{const tolerance=(r.tolerance_bps??300)/100,bad=Math.abs(r.yield_variance)>tolerance;return `<tr><td><strong>RUN-${r.id}</strong><small>${date(r.run_date)}</small></td><td>${esc(r.product)}<small>${r.batch_count} batch${r.batch_count>1?'es':''}</small></td><td>${number(r.expected)} ${esc(r.unit)}</td><td>${number(r.actual)} ${esc(r.unit)}${r.scrap?`<small>${number(r.scrap)} scrap</small>`:''}</td><td>${bad?`<span class="variance bad">${r.yield_variance.toFixed(1)}%</span>`:`<span class="variance good">${r.yield_variance.toFixed(1)}%</span>`}</td><td>${money(r.total_cost)}</td><td>${money(r.cost_per_unit)}</td><td><button class="text-button" data-run="${r.id}">Details</button></td></tr>`});html+=`<section class="panel"><div class="panel-heading"><div><h2>Production history</h2><p>Planned against actual output and material consumption</p></div></div>${table(['Run','Product','Expected output','Good output','Yield variance','Run cost','Cost / unit',''],rows,'No production runs posted.')}</section><div class="panel-grid"><section class="panel"><div class="panel-heading"><div><h2>Recipe and stock readiness</h2><p>Current materials and packaging</p></div></div>${table(['Material','Recipe / batch','Available'],state.boot.bom.filter(b=>products.some(p=>p.id===b.product_id)).map(b=>`<tr><td>${esc(b.material)}</td><td>${number(b.qty_milli/1000)} ${esc(b.unit)}</td><td>${number(state.boot.items.find(i=>i.id===b.material_id)?.stock||0)} ${esc(b.stock_unit)}</td></tr>`))}</section><section class="panel"><div class="panel-heading"><div><h2>Variance signals</h2><p>Material deviations beyond recipe tolerance</p></div></div><div class="signal-list">${runs.slice(0,3).map(r=>r.inputs.map(i=>{const warn=Math.abs(i.variance)>(r.tolerance_bps??300)/100;return `<div class="signal"><span class="kind-dot ${warn?'warning':'ok'}"></span><div><strong>${esc(i.name)}</strong><small>RUN-${r.id} · ${number(i.actual)} actual / ${number(i.planned)} planned</small></div><span class="${warn?'warning-text':'subtle'}">${i.variance>0?'+':''}${i.variance.toFixed(1)}%${warn?' · review':''}</span></div>`}).join('')).join('')||'<p class="empty-cell">Variances appear after the first run.</p>'}</div></section></div>`;
  render(html);$('#new-run')?.addEventListener('click',()=>newProductionRun(products,materials));$$('[data-run]').forEach(b=>b.onclick=()=>runDetails(runs.find(r=>r.id===Number(b.dataset.run))));}
async function newProductionRun(products,materials){if(!products.length)return;const categories=['Labour','Gas and power','Other overhead'];modalForm('Record a production run',`<form id="run-form"><div class="form-grid"><div class="span-2">${selectField('Finished product','product_id',products.map(p=>({value:p.id,label:p.name})))}</div>${field('Production date','run_date','date',state.boot.today)}${field('Number of batches','batch_count','number','1','min="1" step="1"')}<div class="span-2 output-preview" id="output-preview"></div><div class="span-2"><div class="eyebrow section-eyebrow">RAW AND PACKAGING INPUTS</div><div id="run-inputs"></div></div><div class="span-2">${field('Actual good output','actual_output','number','188','min="1" step="0.001 required')}</div><div class="span-2">${field('Finished product scrap','scrap','number','0','min="0" step="0.001')}</div><div class="span-2"><div class="eyebrow section-eyebrow">RUN OVERHEADS</div><div class="form-grid">${categories.map((x,i)=>field(`${x} · ₹`, `expense-${i}`, 'number',i===0?'1200':i===1?'600':'0','min="0" step="0.01"')).join('')}</div></div><div class="span-2">${field('Production note','note')}</div></div></form>`,'Post run');const form=$('#run-form'),productSel=$('[name=product_id]',form),batch=$('[name=batch_count]',form);const setRecipe=()=>{const pid=Number(productSel.value),recipe=state.boot.recipes.find(r=>r.product_id===pid),expected=recipe?recipe.expected_yield_milli/1000:0;const bom=state.boot.bom.filter(b=>b.product_id===pid);$('#output-preview').textContent=`Expected good output: ${number(expected*Number(batch.value||1))} ${esc(products.find(p=>p.id===pid)?.unit||'units')}`;$('#run-inputs').innerHTML=bom.map(b=>{const it=materials.find(i=>i.id===b.material_id);return `<div class="production-input" data-material="${it.id}"><div class="input-name"><strong>${esc(it.name)}</strong><small>Recipe ${number(b.qty_milli/1000)} ${esc(it.unit)} / batch · available ${number(it.stock)} ${esc(it.unit)}</small></div><label class="field"><span>Total consumed</span><input type="number" min="0" step="0.001" name="actual-${it.id}" value="${number(b.qty_milli/1000*Number(batch.value||1))}"></label><label class="field"><span>Damaged within total</span><input type="number" min="0" step="0.001" name="damaged-${it.id}" value="0"></label></div>`}).join('');};productSel.onchange=setRecipe;batch.oninput=setRecipe;setRecipe();
  $('#modal-submit').onclick=async()=>{try{const n=Number(batch.value||1);const inputs=$$('.production-input',form).map(r=>({material_id:Number(r.dataset.material),actual:Number($(`[name="actual-${r.dataset.material}"]`,r).value),damaged:Number($(`[name="damaged-${r.dataset.material}"]`,r).value),unit:materials.find(i=>i.id===Number(r.dataset.material)).unit}));const expenses=categories.map((category,i)=>({category,amount:Number($(`[name="expense-${i}"]`,form).value||0)})).filter(e=>e.amount>0);const payload={product_id:Number(productSel.value),run_date:$('[name=run_date]',form).value,batch_count:n,actual_output:Number($('[name=actual_output]',form).value),scrap:Number($('[name=scrap]',form).value||0),inputs,expenses,note:$('[name=note]',form).value};const r=await api('/production',{method:'POST',body:payload});$('#modal')?.remove();toast(`RUN-${r.id} posted. Cost ${money(r.cost)} · ${money(r.cost_per_unit)} per finished unit.`);state.cache={};state.boot=await api('/bootstrap');await renderPage()}catch(e){toast(e.message,'error')}};}
function runDetails(r){if(!r)return;const tol=(r.tolerance_bps??300)/100,rows=r.inputs.map(i=>`<tr><td>${esc(i.name)}</td><td>${number(i.planned)} ${esc(i.unit)}</td><td>${number(i.actual)} ${esc(i.unit)}</td><td>${number(i.damaged)} ${esc(i.unit)}</td><td>${(i.variance>0?'+':'')+i.variance.toFixed(1)}% ${Math.abs(i.variance)>tol?'<span class="warning-text">Flag</span>':''}</td><td>${money(i.unit_cost_paise)}</td></tr>`).join('');modalForm(`RUN-${r.id} · ${esc(r.product)}`,`<div class="stat-grid compact-grid">${stat('Expected output',number(r.expected),'finished units','◫')}${stat('Good output',number(r.actual),'finished units','✓')}${stat('Run cost',money(r.total_cost),'materials + overhead','₹')}${stat('Cost per unit',money(r.cost_per_unit),'weighted average inputs','◉')}</div>${table(['Material','Planned','Issued','Damaged','Variance','Unit cost'],rows)}<p class="subtle">Yield variance: ${r.yield_variance.toFixed(1)}%. Alerts trigger beyond ${number(tol,1)}% tolerance.</p>`,'Close');$('#modal-submit').onclick=()=>$('#modal').remove();}

async function inventoryPage(){const items=state.boot.items;let html=heading('INVENTORY CONTROL','Stock and movement ledger','Every balance comes from opening stock, receipts, production issues, production output and dispatch postings.',can('admin','owner')?'<button class="button button-soft" id="new-adjustment">± Stock adjustment</button> <button class="button button-primary" id="new-purchase">＋ Record purchase</button>':'');html+=`<div class="stock-cards">${items.map(i=>`<div class="stock-card"><div class="kind-label">${esc(i.kind)} · ${esc(i.sku)}</div><strong>${esc(i.name)}</strong><div class="stock-amount ${i.stock_milli<=i.reorder_milli&&i.reorder_milli>0?'warning-text':''}">${number(i.stock)} <small>${esc(i.unit)}</small></div><div class="subtle">${i.stock_milli<=i.reorder_milli&&i.reorder_milli>0?'Reorder threshold reached':`Last weighted rate ${money(i.cost)}`}</div></div>`).join('')}</div>`;
  const moves=await api('/stock-movements?limit=80');
  html+=`<section class="panel"><div class="panel-heading"><div><h2>Movement ledger</h2><p>Latest 80 source-linked stock movements</p></div><a class="button button-soft" href="/api/export/stock">Download full CSV</a></div>${table(['Movement','Date','Item','Quantity','Source document','Lot / expiry','Rate'],moves.map(m=>`<tr><td>#${m.id}</td><td>${esc(m.created_at)}</td><td><strong>${esc(m.name)}</strong><small>${esc(m.sku)}</small></td><td class="${m.quantity<0?'negative':'positive'}">${m.quantity>0?'+':''}${number(m.quantity)} ${esc(m.unit)}</td><td>${esc(m.source_type)}<small>${esc(m.reference)}</small></td><td>${esc(m.lot||'—')} ${m.expiry_date?`<small>Exp ${esc(m.expiry_date)}</small>`:''}</td><td>${money(m.unit_cost)}</td></tr>`),'No stock movements.')}</section>`;render(html);$('#new-purchase')?.addEventListener('click',newPurchase);$('#new-adjustment')?.addEventListener('click',newAdjustment);}
async function newAdjustment(){const items=state.boot.items;modalForm('Post a stock adjustment',`<form id="adjust-form" class="form-grid">${selectField('Stock item','item_id',items.map(i=>({value:i.id,label:`${i.name} · current ${number(i.stock)} ${i.unit}`})))}${selectField('Adjustment','direction',[{value:'increase',label:'Increase stock'},{value:'decrease',label:'Decrease stock'}])}${field('Quantity','quantity','number','1','min="0.001" step="0.001"')}${field('Reason (required)','reason')}${field('Reference','reference')}${field('Lot / batch','lot')}${field('Expiry','expiry','date')}</form>`,'Post adjustment');$('#modal-submit').onclick=async()=>{try{await api('/adjustments',{method:'POST',body:readForm($('#adjust-form'))});$('#modal').remove();state.boot=await api('/bootstrap');toast('Adjustment recorded in the stock ledger.');await renderPage()}catch(e){toast(e.message,'error')}};}
async function newPurchase(){const items=state.boot.items.filter(i=>i.kind!=='finished');const suppliers=state.boot.suppliers;let lines=[{}];modalForm('Receive a purchase',`<form id="purchase-form" class="form-grid">${selectField('Supplier','supplier_id',[{value:'',label:'Select supplier'},...suppliers.map(s=>({value:s.id,label:s.name}))])}${field('Purchase date','purchase_date','date',state.boot.today)}${field('Supplier invoice / reference','supplier_reference')}<div class="span-2" id="purchase-lines"><div class="purchase-line"><label class="field"><span>Item</span><select name="item_id">${items.map(i=>`<option value="${i.id}">${esc(i.name)} · ${esc(i.unit)}</option>`).join('')}</select></label><label class="field"><span>Quantity</span><input name="quantity" type="number" min="0.001" step="0.001" value="60"></label><label class="field"><span>Rate · ₹ / unit</span><input name="rate" type="number" min="0" step="0.01" value="45"></label><label class="field"><span>Lot / batch</span><input name="lot"></label><label class="field"><span>Expiry date</span><input name="expiry" type="date"></label><button type="button" class="icon-btn remove-purchase">×</button></div></div><button type="button" id="add-purchase-line" class="button button-quiet span-2">＋ Add line</button>${field('Note','note')}</form>`,'Post receipt');$('#add-purchase-line').onclick=()=>{$('#purchase-lines').insertAdjacentHTML('beforeend',`<div class="purchase-line"><label class="field"><span>Item</span><select name="item_id">${items.map(i=>`<option value="${i.id}">${esc(i.name)} · ${esc(i.unit)}</option>`).join('')}</select></label><label class="field"><span>Quantity</span><input name="quantity" type="number" min="0.001" step="0.001" value="1"></label><label class="field"><span>Rate · ₹ / unit</span><input name="rate" type="number" min="0" step="0.01" value="0"></label><label class="field"><span>Lot / batch</span><input name="lot"></label><label class="field"><span>Expiry date</span><input name="expiry" type="date"></label><button type="button" class="icon-btn remove-purchase">×</button></div>`);$$('.remove-purchase').forEach(b=>b.onclick=()=>b.closest('.purchase-line').remove());};$$('.remove-purchase').forEach(b=>b.onclick=()=>b.closest('.purchase-line').remove());$('#modal-submit').onclick=async()=>{try{const f=$('#purchase-form'),ls=$$('.purchase-line',f).map(r=>({item_id:Number($('[name=item_id]',r).value),quantity:Number($('[name=quantity]',r).value),rate:Number($('[name=rate]',r).value),lot:$('[name=lot]',r).value,expiry:$('[name=expiry]',r).value}));const result=await api('/purchases',{method:'POST',body:{supplier_id:$('[name=supplier_id]',f).value||null,purchase_date:$('[name=purchase_date]',f).value,supplier_reference:$('[name=supplier_reference]',f).value,lines:ls,note:$('[name=note]',f).value}});$('#modal')?.remove();toast(`Purchase receipt #${result.id} posted to stock.`);state.boot=await api('/bootstrap');state.cache={};await renderPage()}catch(e){toast(e.message,'error')}};}

async function invoicesPage(){const list=await api('/invoices');let html=heading('BILLING & COLLECTIONS','Invoices and receivables','Issued GST invoices, collection entry and customer balances.',can('admin','owner')?'<a class="button button-soft" href="/api/export/receivables">Receivables CSV</a>':'');const rows=list.map(i=>`<tr><td><strong>${esc(i.number)}</strong><small>${date(i.invoice_date)}</small></td><td><strong>${esc(i.customer)}</strong><small>${esc(i.customer_state)} · ${esc(i.gstin)}</small></td><td>${money(i.taxable)}</td><td>${i.cgst?`CGST ${money(i.cgst)}<br>SGST ${money(i.sgst)}`:`IGST ${money(i.igst)}`}</td><td>${money(i.total)}</td><td>${money(i.paid)}</td><td class="${i.outstanding?'warning-text':'positive'}">${money(i.outstanding)}</td><td>${badge(i.status)}${i.credit_number?`<small>${esc(i.credit_number)}</small>`:''}</td><td><a class="button button-soft button-small" href="/api/invoices/${i.id}.pdf" target="_blank">PDF</a>${can('admin','owner')&&i.outstanding?` <button class="button button-primary button-small" data-payment="${i.id}" data-balance="${i.outstanding}">Record payment</button>`:''}${can('admin','owner')&&i.status==='posted'&&!i.paid?` <button class="text-button danger-text" data-credit="${i.id}">Credit note</button>`:''}</td></tr>`);html+=`<section class="panel">${table(['Invoice','Bill to','Taxable','GST split','Total','Collected','Outstanding','Status',''],rows,'Invoices will appear after admin approval.')}</section>`;render(html);$$('[data-payment]').forEach(b=>b.onclick=()=>recordPayment(Number(b.dataset.payment),Number(b.dataset.balance)));$$('[data-credit]').forEach(b=>b.onclick=()=>creditInvoice(Number(b.dataset.credit)));}
async function recordPayment(id,balance){modalForm('Record customer payment',`<form id="payment-form" class="form-grid">${field('Amount received · ₹','amount','number',balance.toFixed(2),`min="0.01" max="${balance}" step="0.01" required`)}${field('Payment date','payment_date','date',state.boot.today)}${selectField('Method','method',['Bank transfer','Cash','UPI','Cheque'].map(x=>({value:x,label:x})))}${field('Reference / transaction ID','reference')}</form>`,'Post collection');$('#modal-submit').onclick=async()=>{try{await api(`/invoices/${id}/payments`,{method:'POST',body:readForm($('#payment-form'))});$('#modal')?.remove();toast('Collection recorded against the invoice.');state.cache={};await renderPage()}catch(e){toast(e.message,'error')}};}
async function creditInvoice(id){const inv=(await api('/invoices')).find(i=>i.id===id);if(!inv)return;modalForm(`Credit invoice ${esc(inv.number)}`,`<form id="credit-form" class="form-grid"><div class="span-2"><p class="modal-intro">This creates a full credit note for ${money(inv.total)}. The posted invoice remains in the audit history.</p></div>${field('Credit note date','credit_date','date',state.boot.today)}${selectField('Returned goods','goods_returned',[{value:'true',label:'Goods returned to finished stock'},{value:'false',label:'Goods not returned'}])}<div class="span-2">${field('Reason (required)','reason','text','','required')}</div></form>`,'Issue credit note');$('#modal-submit').onclick=async()=>{try{const f=readForm($('#credit-form'));f.goods_returned=f.goods_returned==='true';const r=await api(`/invoices/${id}/credit-note`,{method:'POST',body:f});$('#modal').remove();toast(`Credit note ${r.number} posted. Invoice history retained.`);state.boot=await api('/bootstrap');state.cache={};await renderPage()}catch(e){toast(e.message,'error')}};}

async function reportsPage(){const from=$('#report-from')?.value||state.boot.today.slice(0,7)+'-01',to=$('#report-to')?.value||state.boot.today;const r=await api(`/reports?from=${from}&to=${to}`);const html=heading('ACCOUNTS & AUDIT','Monthly reports','Date-filtered sales, GST, purchasing, stock, production costing and collections.',`<button class="button button-soft" id="print-report">Print / Save PDF</button>`)+`<section class="panel report-filter"><label>From<input id="report-from" type="date" value="${esc(from)}"></label><label>To<input id="report-to" type="date" value="${esc(to)}"></label><button class="button button-primary" id="run-report">Run report</button><span class="filter-spacer"></span><span class="subtle">${date(from)} to ${date(to)}</span></section><div class="stat-grid">${stat('Taxable sales',money(r.summary.taxable),`${r.summary.invoice_count} invoices`,'↗')}${stat('Output GST',money(r.summary.tax),`CGST + SGST + IGST`,'▤')}${stat('Purchases',money(r.summary.purchases),'Raw and packaging receipts','↓')}${stat('Open receivables',money(r.summary.open_receivables),'Outstanding for selected period','◷')}</div><div class="export-grid">${[['sales','Sales and GST'],['purchases','Purchase register'],['stock','Stock ledger'],['production','Production costing'],['receivables','Collections & ageing'],['credit-notes','Credit notes']].map(x=>`<a class="export-card" href="/api/export/${x[0]}?from=${from}&to=${to}"><span class="export-icon">⇩</span><div><strong>${x[1]} CSV</strong><small>Download filtered report</small></div></a>`).join('')}</div><div class="report-tabs"><button class="report-tab active" data-tab="sales">Sales & GST</button><button class="report-tab" data-tab="production">Production</button><button class="report-tab" data-tab="receivables">Receivables</button><button class="report-tab" data-tab="stock">Stock summary</button><button class="report-tab" data-tab="credit-notes">Credit notes</button></div><div id="report-body">${reportTable('sales',r)}</div>`;
  render(html);$('#run-report').onclick=reportsPage;$('#print-report').onclick=()=>window.print();$$('[data-tab]').forEach(b=>b.onclick=()=>{$$('.report-tab').forEach(x=>x.classList.toggle('active',x===b));$('#report-body').innerHTML=reportTable(b.dataset.tab,r)});}
function reportTable(tab,r){if(tab==='sales')return `<section class="panel"><h2>Sales register and GST</h2>${table(['Invoice','Customer','Date','Taxable','CGST','SGST','IGST','Total'],r.sales.map(i=>`<tr><td>${esc(i.number)}</td><td>${esc(i.customer)}<small>${esc(i.state)}</small></td><td>${date(i.invoice_date)}</td><td>${money(i.taxable)}</td><td>${money(i.cgst)}</td><td>${money(i.sgst)}</td><td>${money(i.igst)}</td><td><strong>${money(i.total)}</strong></td></tr>`),'No sales in this date range.')}</section><section class="panel"><h2>Customer-wise taxable sales</h2>${table(['Customer','Invoices','Taxable value'],r.customer_sales.map(i=>`<tr><td>${esc(i.name)}</td><td>${i.invoices}</td><td>${money(i.taxable)}</td></tr>`))}</section><section class="panel"><h2>Product-wise sales</h2>${table(['Product','SKU','Quantity sold','Taxable value'],r.product_sales.map(i=>`<tr><td>${esc(i.name)}</td><td>${esc(i.sku)}</td><td>${number(i.quantity)} ${esc(i.unit)}</td><td>${money(i.taxable)}</td></tr>`),'No product sales for this period.')}</section>`;
  if(tab==='production')return `<section class="panel">${table(['Run','Date','Product','Planned output','Actual good output','Yield variance','Total cost','Cost / unit'],r.production.map(i=>`<tr><td>RUN-${i.id}</td><td>${date(i.run_date)}</td><td>${esc(i.product)}</td><td>${number(i.expected)}</td><td>${number(i.actual)}</td><td class="${Math.abs(i.yield_variance)>3?'warning-text':''}">${i.yield_variance.toFixed(1)}%</td><td>${money(i.cost)}</td><td>${money(i.cost_per_unit)}</td></tr>`),'No runs in this date range.')}</section>`;
  if(tab==='receivables')return `<section class="panel">${table(['Invoice','Date','Customer','Invoice total','Paid','Balance','Age'],r.receivables.map(i=>{const days=Math.floor((Date.now()-new Date(i.invoice_date+'T00:00:00'))/86400000);return `<tr><td>${esc(i.number)}</td><td>${date(i.invoice_date)}</td><td>${esc(i.customer)}</td><td>${money(i.total)}</td><td>${money(i.paid)}</td><td>${money(i.outstanding)}</td><td>${days} days</td></tr>`}),'No outstanding receivables.')}</section>`;
  if(tab==='credit-notes')return `<section class="panel">${table(['Credit note','Date','Invoice','Customer','Reason','Taxable','GST total','Goods back'],r.credit_notes.map(i=>`<tr><td>${esc(i.number)}</td><td>${date(i.credit_date)}</td><td>${esc(i.invoice)}</td><td>${esc(i.customer)}</td><td>${esc(i.reason)}</td><td>${money(i.taxable_paise/100)}</td><td>${money(i.total)}</td><td>${i.goods_returned?'Yes':'No'}</td></tr>`),'No credit notes in this period.')}</section>`;
  return `<section class="panel">${table(['SKU','Item','Type','On hand','Unit'],r.stock.map(i=>`<tr><td>${esc(i.sku)}</td><td>${esc(i.name)}</td><td>${esc(i.kind)}</td><td>${number(i.on_hand)}</td><td>${esc(i.unit)}</td></tr>`))}</section>`;}

async function mastersPage(){const b=state.boot;let html=heading('CONFIGURATION','Masters and access','Maintain the small set of records that makes transactions traceable.');html+=`<div class="report-tabs"><button class="report-tab active" data-master="items">Products & materials</button><button class="report-tab" data-master="customers">Customers</button><button class="report-tab" data-master="suppliers">Suppliers</button><button class="report-tab" data-master="recipes">Bills of materials</button>${can('owner')?'<button class="report-tab" data-master="users">User access</button>':''}</div><div id="master-body">${masterTable('items',b)}</div>`;render(html);$$('[data-master]').forEach(btn=>btn.onclick=()=>{$$('.report-tab').forEach(x=>x.classList.toggle('active',x===btn));$('#master-body').innerHTML=masterTable(btn.dataset.master,state.boot);bindMaster(btn.dataset.master)});bindMaster('items');}
function masterTable(tab,b){if(tab==='items')return `<section class="panel"><div class="panel-heading"><div><h2>Item master</h2><p>Finished goods, raw material and packaging</p></div><button class="button button-primary" id="add-item">＋ Add item</button></div>${table(['SKU','Description','Category','Unit','Price ₹','GST','Stock'],b.items.map(i=>`<tr><td>${esc(i.sku)}</td><td><strong>${esc(i.name)}</strong><small>HSN ${esc(i.hsn)}</small></td><td>${esc(i.kind)}</td><td>${esc(i.unit)}</td><td>${money(i.sell_price)}</td><td>${i.tax_bps/100}%</td><td>${number(i.stock)} ${esc(i.unit)}</td></tr>`))}</section>`;
  if(tab==='customers')return `<section class="panel"><div class="panel-heading"><div><h2>Customer accounts</h2><p>Place of supply determines intra-state or inter-state GST.</p></div><button class="button button-primary" id="add-customer">＋ Add customer</button></div>${table(['Customer','Type','State','GSTIN','Salesman','Address'],b.customers.map(c=>`<tr><td><strong>${esc(c.name)}</strong></td><td>${esc(c.type)}</td><td>${esc(c.state)}</td><td>${esc(c.gstin)}</td><td>${esc(b.users.find(u=>u.id===c.salesman_id)?.display_name||'Unassigned')}</td><td>${esc(c.address)}</td></tr>`))}</section>`;
  if(tab==='suppliers')return `<section class="panel"><div class="panel-heading"><div><h2>Supplier directory</h2><p>Supplier references are retained on each purchase receipt.</p></div><button class="button button-primary" id="add-supplier">＋ Add supplier</button></div>${table(['Supplier','GSTIN','State','Phone'],b.suppliers.map(s=>`<tr><td>${esc(s.name)}</td><td>${esc(s.gstin)}</td><td>${esc(s.state)}</td><td>${esc(s.phone)}</td></tr>`),'Add suppliers as you record receipts.')}</section>`;
  if(tab==='recipes')return `<section class="panel"><div class="panel-heading"><div><h2>Bill of materials</h2><p>Standard material quantities for one production batch</p></div><label class="field compact-field"><span>Product</span><select id="bom-product">${b.items.filter(i=>i.kind==='finished').map(i=>`<option value="${i.id}">${esc(i.name)}</option>`)}</select></label></div><div id="bom-editor"></div></section>`;
  if(tab==='users')return `<section class="panel"><div class="panel-heading"><div><h2>Accounts and roles</h2><p>Permissions follow role-specific daily tasks.</p></div><button class="button button-primary" id="add-user">＋ Add account</button></div>${table(['Name','Login','Role','Status'],b.users.map(u=>`<tr><td>${esc(u.display_name)}</td><td>${esc(u.username)}</td><td>${esc(b.role_names[u.role])}</td><td>${u.active?'Active':'Disabled'}</td></tr>`))}</section>`;return ''}
function bindMaster(tab){if(tab==='items')$('#add-item')?.addEventListener('click',addItem);if(tab==='customers')$('#add-customer')?.addEventListener('click',addCustomer);if(tab==='suppliers')$('#add-supplier')?.addEventListener('click',addSupplier);if(tab==='users')$('#add-user')?.addEventListener('click',addUser);if(tab==='recipes'){const select=$('#bom-product');select?.addEventListener('change',()=>bomEditor(Number(select.value)));if(select)bomEditor(Number(select.value));}}
function addItem(){const kinds=[['finished','Finished goods'],['raw','Raw material'],['packaging','Packaging']];modalForm('Add product or material',`<form id="item-form" class="form-grid">${field('Name','name')}${field('SKU / code','sku')}${selectField('Item type','kind',kinds.map(x=>({value:x[0],label:x[1]})))}${selectField('Stock unit','unit',['packet','piece','kg','g','litre','ml','carton'].map(x=>({value:x,label:x})))}${field('Selling price · ₹','sell_price','number','0','min="0" step="0.01"')}${field('Standard cost · ₹ / unit','cost','number','0','min="0" step="0.01"')}${field('GST rate · %','tax_rate','number','5','min="0" step="0.01"')}${field('HSN code','hsn')}${field('Reorder level','reorder','number','0','min="0" step="0.001"')}${field('Packets per carton','pack_size','number','20','min="0.001" step="0.001"')}${field('Expected batch yield · finished items','expected_yield','number','200','min="0.001" step="0.001')}</form>`);$('#modal-submit').onclick=async()=>{try{await api('/items',{method:'POST',body:readForm($('#item-form'))});$('#modal').remove();state.boot=await api('/bootstrap');toast('Item master added.');await mastersPage()}catch(e){toast(e.message,'error')}};}
function addCustomer(){const sales=state.boot.users.filter(u=>u.role==='salesman');modalForm('Add customer',`<form id="customer-form" class="form-grid">${field('Business name','name')}${selectField('Customer type','type',['retailer','distributor'].map(x=>({value:x,label:titleCase(x)})))}${field('State / place of supply','state','text','Tamil Nadu')}${field('GSTIN','gstin')}${field('Billing address','address','text','','class="span-2"')}${selectField('Assigned salesman','salesman_id',[{value:'',label:'Unassigned'},...sales.map(u=>({value:u.id,label:u.display_name}))])}</form>`);$('#modal-submit').onclick=async()=>{try{await api('/customers',{method:'POST',body:readForm($('#customer-form'))});$('#modal').remove();state.boot=await api('/bootstrap');toast('Customer added.');await mastersPage()}catch(e){toast(e.message,'error')}};}
function addSupplier(){modalForm('Add supplier',`<form id="supplier-form" class="form-grid">${field('Supplier name','name')}${field('GSTIN','gstin')}${field('State','state','text','Tamil Nadu')}${field('Phone','phone')}</form>`);$('#modal-submit').onclick=async()=>{try{await api('/suppliers',{method:'POST',body:readForm($('#supplier-form'))});$('#modal').remove();state.boot=await api('/bootstrap');toast('Supplier added.');await mastersPage()}catch(e){toast(e.message,'error')}};}
function addUser(){modalForm('Create account',`<form id="user-form" class="form-grid">${field('Display name','display_name')}${field('Username','username')}${selectField('Role','role',Object.entries(state.boot.role_names).map(([value,label])=>({value,label})))}${field('Initial password','password','password','','minlength="8"')}</form>`);$('#modal-submit').onclick=async()=>{try{await api('/users',{method:'POST',body:readForm($('#user-form'))});$('#modal').remove();state.boot=await api('/bootstrap');toast('User account created.');await mastersPage()}catch(e){toast(e.message,'error')}};}
function bomEditor(product){const items=state.boot.items.filter(i=>i.kind!=='finished'),current=state.boot.bom.filter(x=>x.product_id===product),recipe=state.boot.recipes.find(r=>r.product_id===product);$('#bom-editor').innerHTML=`<form id="bom-form">${field('Expected finished output per batch','expected_yield','number',recipe?recipe.expected_yield_milli/1000:200,'min="0.001" step="0.001"')}${field('Variance alert tolerance · %','tolerance','number',recipe?recipe.tolerance_bps/100:3,'min="0" step="0.1"')}<div id="bom-lines">${current.map(x=>bomLine(items,x.material_id,x.qty_milli/1000)).join('')}</div><div class="form-actions"><button type="button" id="bom-add" class="button button-quiet">＋ Add material</button><span class="filter-spacer"></span><button type="button" id="bom-save" class="button button-primary">Save recipe</button></div></form>`;$('#bom-add').onclick=()=>{$('#bom-lines').insertAdjacentHTML('beforeend',bomLine(items,null,1));bindBomRemove()};bindBomRemove();$('#bom-save').onclick=async()=>{try{const f=$('#bom-form'),lines=$$('.bom-line',f).map(l=>({material_id:Number($('[name=material_id]',l).value),quantity:Number($('[name=quantity]',l).value),unit:$('[name=unit]',l).value}));await api(`/items/${product}/bom`,{method:'PUT',body:{lines,expected_yield:Number($('[name=expected_yield]',f).value),tolerance:Number($('[name=tolerance]',f).value)}});state.boot=await api('/bootstrap');localStorage.setItem('offline-session',JSON.stringify({user:state.user,boot:state.boot}));toast('Bill of materials and batch yield saved.');mastersPage()}catch(e){toast(e.message,'error')}};}
function bindBomRemove(){$$('.remove-bom').forEach(b=>b.onclick=()=>b.closest('.bom-line').remove());$$('.bom-line').forEach(row=>{const material=$('[name=material_id]',row),unit=$('[name=unit]',row);material.onchange=()=>{const item=state.boot.items.find(i=>i.id===Number(material.value)),family={kg:['kg','g'],g:['g','kg'],litre:['litre','ml'],l:['litre','ml'],ml:['ml','litre'],piece:['piece','pieces'],pieces:['pieces','piece'],packet:['packet','packets'],packets:['packets','packet'],carton:['carton','cartons'],cartons:['cartons','carton']};unit.innerHTML=(family[item.unit]||[item.unit]).map(u=>`<option value="${u}" ${u===item.unit?'selected':''}>${u}</option>`).join('')}})}
function bomLine(items,id,value){const selected=items.find(i=>i.id===id)||items[0];const family={kg:['kg','g'],g:['g','kg'],litre:['litre','ml'],l:['litre','ml'],ml:['ml','litre'],piece:['piece','pieces'],pieces:['pieces','piece'],packet:['packet','packets'],packets:['packets','packet'],carton:['carton','cartons'],cartons:['cartons','carton']};const units=family[selected?.unit]||[selected?.unit];return `<div class="bom-line"><label class="field"><span>Material / packaging</span><select name="material_id">${items.map(i=>`<option value="${i.id}" ${i.id===selected?.id?'selected':''}>${esc(i.name)} · ${esc(i.unit)}</option>`)}</select></label><label class="field"><span>Quantity / batch</span><input name="quantity" type="number" min="0.001" step="0.001" value="${value}"></label><label class="field"><span>Recipe unit</span><select name="unit">${units.map(u=>`<option value="${u}" ${u===selected?.unit?'selected':''}>${u}</option>`).join('')}</select></label><button type="button" class="icon-btn remove-bom">×</button></div>`}

async function auditPage(){const list=await api('/audit');const rows=list.map(a=>`<tr><td>${esc(a.created_at)}</td><td>${esc(a.display_name||'System')}</td><td>${esc(a.action)}</td><td>${esc(a.entity_type)} ${a.entity_id||''}</td><td>${esc(a.detail)}</td></tr>`);render(heading('TRACEABILITY','Activity log','A time-stamped record of order decisions, receipts, production and collections.')+`<section class="panel">${table(['Timestamp','User','Action','Record','Details'],rows,'No actions have been logged yet.')}</section>`)}

function render(content){$('#app').innerHTML=shell(content);$$('[data-page]').forEach(b=>b.onclick=()=>navigate(b.dataset.page));$('#logout')?.addEventListener('click',logout);$('#mobile-menu')?.addEventListener('click',()=>$('.sidebar').classList.toggle('show'));$('#mobile-sync')?.addEventListener('click',syncOffline);$('#sync-orders')?.addEventListener('click',syncOffline)}
async function renderPage(){try{switch(state.page){case'dashboard':return await dashboard();case'orders':return await ordersPage();case'production':return await productionPage();case'inventory':return await inventoryPage();case'invoices':return await invoicesPage();case'reports':return await reportsPage();case'masters':return await mastersPage();case'audit':return await auditPage();default:return await dashboard()}}catch(e){if(e.status===401){state.user=null;return loginView()}$('#app').innerHTML=shell(heading('WORKSPACE','Unable to load this page',esc(e.message))+'<button class="button button-soft" id="retry">Try again</button>');$('#retry').onclick=renderPage}}
function navigate(page){state.page=page;history.pushState({page},'',`#${page}`);renderPage();}
async function logout(){try{await api('/auth/logout',{method:'POST'})}catch{}localStorage.removeItem('offline-session');state.user=null;state.boot=null;state.cache={};loginView()}
function loginView(error=''){const roles=[['admin','admin123','Factory admin'],['salesman_a','sales123','Salesman A'],['salesman_b','sales123','Salesman B'],['production','prod123','Production'],['auditor','audit123','Auditor'],['owner','owner123','Owner']];$('#app').innerHTML=`<main class="login-page"><div class="login-brand"><div class="brand-mark large">SF</div><div><strong>Sample Foods</strong><span>Factory operations</span></div></div><section class="login-card"><div class="eyebrow">ORDER TO AUDIT</div><h1>Welcome back</h1><p class="muted">Sign in to your workspace to continue.</p>${error?`<div class="form-error">${esc(error)}</div>`:''}<form id="login-form"><label class="field"><span>Username</span><input name="username" autocomplete="username" required></label><label class="field"><span>Password</span><input name="password" type="password" autocomplete="current-password" required></label><button class="button button-primary full-width" type="submit">Sign in <span>→</span></button></form><div class="demo-users"><button id="show-demos" class="text-button">Show demo accounts</button><div id="demo-list" hidden>${roles.map(r=>`<button class="demo-account" data-user="${r[0]}" data-pass="${r[1]}"><span>${r[2]}</span><small>${r[0]}</small></button>`).join('')}</div></div></section><div class="login-foot">Private local demo · data stays in this folder</div></main>`;$('#login-form').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));try{const r=await api('/auth/login',{method:'POST',body:d});state.user=r.user;state.boot=await api('/bootstrap');localStorage.setItem('offline-session',JSON.stringify({user:state.user,boot:state.boot}));state.page=location.hash.slice(1)||'dashboard';await syncOfflineQuiet();renderPage()}catch(err){loginView(err.message)}};$('#show-demos').onclick=()=>$('#demo-list').hidden=!$('#demo-list').hidden;$$('.demo-account').forEach(b=>b.onclick=()=>{$('[name=username]').value=b.dataset.user;$('[name=password]').value=b.dataset.pass;$('#login-form').requestSubmit()});}
async function syncOfflineQuiet(){if(!state.offlineQueue.length||!navigator.onLine)return;for(const order of [...state.offlineQueue]){try{await api('/orders',{method:'POST',body:order});state.offlineQueue.shift()}catch{break}}localStorage.setItem('offline-orders',JSON.stringify(state.offlineQueue));}
async function start(){if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});window.addEventListener('online',()=>{document.querySelector('.connection span:last-child')?.replaceChildren('Online');if(state.user)syncOffline()});window.addEventListener('offline',()=>{if(state.user)renderPage()});window.addEventListener('popstate',()=>{state.page=location.hash.slice(1)||'dashboard';renderPage()});try{const r=await api('/auth/me');state.user=r.user;state.boot=await api('/bootstrap');localStorage.setItem('offline-session',JSON.stringify({user:state.user,boot:state.boot}));state.page=location.hash.slice(1)||'dashboard';renderPage()}catch{if(!navigator.onLine){try{const cached=JSON.parse(localStorage.getItem('offline-session')||'null');if(cached){state.user=cached.user;state.boot=cached.boot;state.page=location.hash.slice(1)||'dashboard';return renderPage()}}catch{}}loginView()}}
start();
